59	  const heading = normalizeHeading(ship.heading + Math.sign(input.moveX) * tuning.turnRate);
60	  const speed = nextSpeed(tuning, ship.speed, throttle);
61	  const dx = divTrunc(speed * HEADING_DX[heading]!, HEADING_SCALE);
62	  const dy = divTrunc(speed * HEADING_DY[heading]!, HEADING_SCALE);
