1	import {
2	  INPUT_HOLD_FRAMES,
3	  MAX_INPUT_MESSAGES_PER_SECOND,
4	  validateInputMessage,
5	  type InputContext,
6	  type InputRejection,
7	} from "@pirate-sea-race/protocol";
8	import { NEUTRAL_INPUT, quantizeAxis, STEPS_PER_SECOND, type PlayerInput } from "@pirate-sea-race/simulation";
9	
10	export type DropReason = InputRejection | "rate-limited";
11	
12	/** A protocol validator: `validateInputMessage` for world input, `validateDuelInputMessage` for duel input. */
13	export type InputValidator<T extends { readonly seq: number }> = (
14	  message: unknown,
15	  context: InputContext,
16	) => { ok: true; input: T } | { ok: false; reason: InputRejection };
17	
18	/**
19	 * The admission both input gates share, so their limits cannot drift apart: at most MAX_INPUT_MESSAGES_PER_SECOND
20	 * messages in each window of STEPS_PER_SECOND room ticks, then the protocol's validation (size, schema, a sequence
21	 * number above the last accepted one, the future-frame limit). Every drop is counted by reason.
22	 */
23	export class InputAdmission<T extends { readonly seq: number }> {
24	  private lastAcceptedSeq = 0;
25	  private windowStart = 0;
26	  private windowCount = 0;
27	  readonly dropped: Record<DropReason, number> = {
28	    "rate-limited": 0,
29	    oversized: 0,
30	    malformed: 0,
31	    "stale-sequence": 0,
32	    "future-frame": 0,
33	  };
34	
35	  constructor(private readonly validate: InputValidator<T>) {}
36	
37	  /**
38	   * Takes one untrusted message at room tick `tick` (for the rate window) when the server's frame is `serverFrame`
39	   * (for the future-frame limit). Returns the accepted message, or why it was dropped.
40	   */
41	  admit(message: unknown, tick: number, serverFrame: number): { ok: true; input: T } | { ok: false; reason: DropReason } {
42	    if (tick - this.windowStart >= STEPS_PER_SECOND) {
43	      this.windowStart = tick;
